// Specificity written as (IDs, classes, types). :is() takes its MOST specific argument,
// even one that matches nothing (#sidebar). :where() always counts as 0.
const variants = [
  [':is(.menu, #sidebar) a  (1,0,1)', '.menu a.link  (0,2,1)', ':where(#nav) a  (0,0,1)'],
  [':is(.menu) a  (0,1,1)', '.menu a.link  (0,2,1)', ':where(#nav) a  (0,0,1)'],
  [':is(.menu, #sidebar) a  (1,0,1)', '.menu a.link  (0,2,1)', ':is(#nav) a  (1,0,1), later in the file'],
];
const rules = document.styleSheets[0].cssRules;
const link = document.querySelector('.link');
const names = { 'rgb(0, 128, 0)': 'green', 'rgb(0, 0, 255)': 'blue', 'rgb(255, 0, 0)': 'red' };

function apply(v) {
  variants[v].forEach((text, i) => { rules[i].selectorText = text.split('  ')[0]; });
  const report = variants[v].join('\n') + '\n=> link is ' + names[getComputedStyle(link).color];
  document.getElementById('out').textContent = report;
  console.log(report);
}
document.querySelectorAll('button').forEach((b) => b.addEventListener('click', () => apply(+b.dataset.v)));
apply(0);
// A selector that matches nothing doesn't invalidate :is() (it takes a forgiving selector list):
console.log('link matches ":is(.menu, #sidebar) a"?', link.matches(':is(.menu, #sidebar) a'));

