// Helper: y of the text baseline in a box (an empty inline-block's bottom edge sits on it).
function baselineOf(box) {
  const probe = document.createElement('span');
  probe.style.cssText = 'display:inline-block;width:0;height:0';
  box.append(probe);
  const y = probe.getBoundingClientRect().bottom;
  probe.remove();
  return y;
}
// Helper: draw a 1px guide line across a box at viewport y.
function guide(box, y, color) {
  const r = box.getBoundingClientRect(), d = document.createElement('div');
  d.style.cssText = 'position:absolute;height:1px;pointer-events:none;background:' + color +
    ';left:' + r.left + 'px;width:' + r.width + 'px;top:' + (y + scrollY) + 'px';
  document.body.append(d);
}
const px = (n) => Math.round(n * 10) / 10 + 'px';
const ctx = document.createElement('canvas').getContext('2d');
for (const p of document.querySelectorAll('.status')) {
  ctx.font = getComputedStyle(p).font;
  const desc = Math.max(ctx.measureText('p').actualBoundingBoxDescent, ctx.measureText('g').actualBoundingBoxDescent);
  const cap = ctx.measureText('S').actualBoundingBoxAscent;
  const base = baselineOf(p), r = p.querySelector('img').getBoundingClientRect();
  guide(p, base, 'red'); guide(p, base + desc, 'blue');
  console.log(p.previousElementSibling.textContent + ':\n  icon bottom is ' + px(r.bottom - base) +
    ' below the baseline; descenders reach ' + px(desc) + ' below it\n  icon top is ' +
    px(base - cap - r.top) + ' above the top of the capital S');
}

explanation:
`vertical-align` applies to **inline-level boxes and table cells**. A `<p>` is a block box, so the declaration on `.label` is ignored (its computed value is `middle`, but it has no effect).

It's also **not inherited**, so the image's computed `vertical-align` stays `baseline`, and nothing moves.

Each inline box aligns itself, so the property belongs on the thing you want to move:

```css
.label img {
  vertical-align: middle;
}
```

Alternatively, center the whole row with `display: flex; align-items: center` on `.label` (and use `gap` for the spacing).

