  background-color: rgb(255, 240, 200);
  padding: 12px;
}

/* Question: the shorthand also sets background-color: transparent */
.alert.warning {
  background: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='20' height='20'><path d='M10 1 L19 18 H1 Z' fill='darkorange'/></svg>") no-repeat left center;
  padding-left: 32px;
}

/* Fix 1: only the image longhands, so .alert's color survives */
.alert.warning-longhand {
  background-image: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='20' height='20'><path d='M10 1 L19 18 H1 Z' fill='darkorange'/></svg>");
  background-repeat: no-repeat;
  background-position: left center;
  padding-left: 32px;
}

/* Fix 2: the color is part of the shorthand */
.alert.warning-full {
  background: rgb(255, 240, 200) url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='20' height='20'><path d='M10 1 L19 18 H1 Z' fill='darkorange'/></svg>") no-repeat left center;
  padding-left: 32px;
}

