nav { position: sticky; height: 30px; background: tomato; color: white; }
main { height: 400px; background: repeating-linear-gradient(#fff 0 20px, #eee 20px 40px); }

/* The only thing that makes sticky stick is a non-auto inset.
   Try top: 20px or bottom: 0 on .v2 and scroll the boxes yourself. */
.v2 { top: 0; }
.v3 { z-index: 10; }
.rel { position: relative; }

